import { useEffect, useState } from "react";
import * as Dialog from "@radix-ui/react-dialog";
import * as Popover from "@radix-ui/react-popover";
import * as Dropdown from "@radix-ui/react-dropdown-menu";
import { ArrowRight, CalendarDays, Check, ChevronDown, Command, Copy, ExternalLink, FolderPlus, MoreHorizontal, PanelRight, Search, Settings2, Trash2, X } from "lucide-react";
import { Badge, IconButton, Section, type Notice } from "./primitives";

type Overlay = "collection" | "drawer" | "confirm" | "command" | null;

function ModalFrame({ title, description, children, drawer = false }: { title: string; description: string; children: React.ReactNode; drawer?: boolean }) {
  return <Dialog.Portal><Dialog.Overlay className="azure-sky azs-dialog-overlay" /><Dialog.Content className={`azure-sky azs-dialog ${drawer ? "azs-drawer" : ""}`}><div className="azs-dialog-heading"><Dialog.Title>{title}</Dialog.Title><Dialog.Close asChild><button className="azs-icon-button" aria-label="Close dialog"><X size={18} /></button></Dialog.Close></div><Dialog.Description className="azs-dialog-description">{description}</Dialog.Description>{children}</Dialog.Content></Dialog.Portal>;
}

export function Overlays({ notify, sections }: { notify: Notice; sections: string[][] }) {
  const [open, setOpen] = useState<Overlay>(null);
  const [name, setName] = useState("");
  const [error, setError] = useState("");
  const [collections, setCollections] = useState<string[]>(() => {
    try { const saved: unknown = JSON.parse(localStorage.getItem("azure-sky:collections") || "null"); return Array.isArray(saved) && saved.every(value => typeof value === "string") ? saved : ["Northbound study"]; } catch { return ["Northbound study"]; }
  });
  const [command, setCommand] = useState("");
  const [commandIndex, setCommandIndex] = useState(0);
  const [date, setDate] = useState("2026-09-09");
  const commandResults = sections.filter(([, title]) => title.toLowerCase().includes(command.toLowerCase()));
  useEffect(() => {
    function keyboard(event: KeyboardEvent) { if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === "k") { event.preventDefault(); setCommand(""); setCommandIndex(0); setOpen("command"); } }
    window.addEventListener("keydown", keyboard);
    return () => window.removeEventListener("keydown", keyboard);
  }, []);
  function updateCollections(next: string[]) {
    try { localStorage.setItem("azure-sky:collections", JSON.stringify(next)); setCollections(next); return true; }
    catch { notify("Browser storage unavailable. Collection was not saved.", "error"); return false; }
  }
  function jump(id: string) { setOpen(null); window.setTimeout(() => document.getElementById(id)?.scrollIntoView({ behavior: "instant" }), 0); }
  return <Section id="overlays" index="05" title="Space for the next thought" trailing={<span className="azs-section-tag"><PanelRight size={14} /> Overlays</span>}>
    <div className="azs-overlay-stage">
      <div className="azs-overlay-actions">
        <Dialog.Root open={open === "collection"} onOpenChange={value => { setOpen(value ? "collection" : null); setError(""); }}><Dialog.Trigger asChild><button className="azs-button"><FolderPlus size={16} />Create collection</button></Dialog.Trigger><ModalFrame title="Create a collection" description="A local collection for this synthetic study."><form onSubmit={event => { event.preventDefault(); if (!name.trim()) { setError("A collection name is required."); return; } if (collections.includes(name.trim())) { setError("A collection with this name already exists."); return; } if (updateCollections([...collections, name.trim()])) { notify(`Collection created: ${name.trim()}`); setName(""); setOpen(null); } }} noValidate><label className="azs-field">Collection name<input autoFocus value={name} onChange={event => setName(event.target.value)} placeholder="Untitled collection" aria-invalid={!!error} aria-describedby={error ? "azs-collection-error" : undefined} /></label><label className="azs-field">Description<textarea rows={3} placeholder="Collection notes..." /></label>{error && <p id="azs-collection-error" className="azs-field-error" role="alert">{error}</p>}<div className="azs-dialog-footer"><Dialog.Close asChild><button type="button" className="azs-button azs-button-secondary">Cancel</button></Dialog.Close><button type="submit" className="azs-button"><Check size={15} />Create</button></div></form></ModalFrame></Dialog.Root>
        <Dialog.Root open={open === "drawer"} onOpenChange={value => setOpen(value ? "drawer" : null)}><Dialog.Trigger asChild><button className="azs-button azs-button-secondary"><PanelRight size={16} />Open inspector</button></Dialog.Trigger><ModalFrame title="Reference details" description="AS-0001 / Cirrus array / synthetic fixture" drawer><div className="azs-drawer-banner"><span className="azs-eyebrow">NORTH OBSERVATORY</span><strong>Cirrus array</strong><Badge tone="success">Reviewed</Badge></div><dl className="azs-detail-list"><div><dt>Reference</dt><dd className="azs-mono">AS-0001</dd></div><div><dt>Owner</dt><dd>Mira Chen</dd></div><div><dt>Records</dt><dd>12,408</dd></div><div><dt>Origin</dt><dd>Local synthetic fixture</dd></div><div><dt>Updated</dt><dd>2026-09-09</dd></div></dl><label className="azs-field">Annotation<textarea defaultValue="Clear upper layers. Retain source provenance with the archive." rows={4} /></label><div className="azs-dialog-footer"><button className="azs-button" onClick={() => { notify("Annotation retained for this open inspector", "info"); }}>Apply annotation</button></div></ModalFrame></Dialog.Root>
        <Popover.Root><Popover.Trigger asChild><button className="azs-button azs-button-secondary"><CalendarDays size={16} />Observation date</button></Popover.Trigger><Popover.Portal><Popover.Content className="azure-sky azs-popover" sideOffset={10}><h3>Observation date</h3><label className="azs-field">Date<input type="date" value={date} onChange={event => setDate(event.target.value)} /></label><div className="azs-popover-readout azs-mono">{date || "No date selected"}</div><Popover.Close className="azs-button">Done</Popover.Close><Popover.Arrow /></Popover.Content></Popover.Portal></Popover.Root>
        <Dialog.Root open={open === "command"} onOpenChange={value => setOpen(value ? "command" : null)}><Dialog.Trigger asChild><button className="azs-button azs-button-secondary"><Command size={16} />Quick switcher</button></Dialog.Trigger><ModalFrame title="Go to section" description="Collection atlas"><div className="azs-command-input"><Search size={18} /><input autoFocus value={command} onChange={event => { setCommand(event.target.value); setCommandIndex(0); }} role="combobox" aria-expanded="true" aria-controls="azs-command-results" aria-autocomplete="list" aria-activedescendant={commandResults.length ? `azs-command-${commandIndex}` : undefined} aria-label="Find a section" placeholder="Find a section..." onKeyDown={event => { if (event.key === "ArrowDown") { event.preventDefault(); setCommandIndex(current => Math.min(commandResults.length - 1, current + 1)); } if (event.key === "ArrowUp") { event.preventDefault(); setCommandIndex(current => Math.max(0, current - 1)); } if (event.key === "Enter" && commandResults[commandIndex]) { event.preventDefault(); jump(commandResults[commandIndex][0]); } }} /></div><div id="azs-command-results" role="listbox" aria-label="Sections" className="azs-command-results">{commandResults.map(([id, title], index) => <button id={`azs-command-${index}`} role="option" aria-selected={index === commandIndex} key={id} onClick={() => jump(id)}><span>{title}</span><ArrowRight size={14} /></button>)}</div>{!commandResults.length && <p className="azs-muted">No matching sections</p>}</ModalFrame></Dialog.Root>
        <div className="azs-row"><Dropdown.Root><Dropdown.Trigger asChild><button className="azs-button azs-button-secondary"><MoreHorizontal size={16} />More actions<ChevronDown size={14} /></button></Dropdown.Trigger><Dropdown.Portal><Dropdown.Content className="azure-sky azs-menu" sideOffset={8}><Dropdown.Item onSelect={() => { setOpen("drawer"); }}><ExternalLink size={14} />Inspect reference</Dropdown.Item><Dropdown.Item onSelect={async () => { try { await navigator.clipboard.writeText("AS-0001"); notify("Reference ID copied"); } catch { notify("Clipboard unavailable", "error"); } }}><Copy size={14} />Copy reference ID</Dropdown.Item><Dropdown.Separator className="azs-menu-separator" /><Dropdown.Item onSelect={() => setOpen("confirm")} disabled={!collections.length}><Trash2 size={14} />Remove last collection</Dropdown.Item></Dropdown.Content></Dropdown.Portal></Dropdown.Root><IconButton label="Open collection settings" onClick={() => setOpen("drawer")}><Settings2 size={19} /></IconButton></div>
        <Dialog.Root open={open === "confirm"} onOpenChange={value => setOpen(value ? "confirm" : null)}><Dialog.Trigger asChild><button className="azs-button azs-button-danger" disabled={!collections.length}><Trash2 size={15} />Remove collection</button></Dialog.Trigger><ModalFrame title="Remove local collection?" description={`"${collections.at(-1) || "Collection"}" will be removed from this browser's specimen list.`}><div className="azs-alert azs-alert-warning"><Trash2 size={18} /><span>Only the local mockup collection is affected.</span></div><div className="azs-dialog-footer"><Dialog.Close asChild><button className="azs-button azs-button-secondary">Keep collection</button></Dialog.Close><button className="azs-button azs-button-danger" onClick={() => { if (updateCollections(collections.slice(0, -1))) { setOpen(null); notify("Local collection removed", "info"); } }}>Remove</button></div></ModalFrame></Dialog.Root>
      </div>
      <div className="azs-overlay-readout"><span className="azs-eyebrow">LOCAL COLLECTIONS</span><strong>{String(collections.length).padStart(2, "0")}</strong><div className="azs-collection-list">{collections.length ? collections.map(collection => <span key={collection}><FolderPlus size={13} />{collection}</span>) : <span>No local collections</span>}</div><span className="azs-mono">OBSERVATION / {date || "UNSET"}</span></div>
    </div>
  </Section>;
}